function evidence = f90_xmech07_extract_reference_evidence( ...
        modelPath, outputDir, officialScenarios, evaluatorAssetRoot)
%F90_XMECH07_EXTRACT_REFERENCE_EVIDENCE One-session six-scenario replay.
% Public parameterization of source authority file presence
% present.
% The native in-memory harness, evidence representation, and reductions below
% are carried mechanically from that current authority.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
    officialScenarios
    evaluatorAssetRoot (1,1) string
end

contract = localOfficialScenarios(officialScenarios);
scenarios = contract.scenarios;
runtimeRoot = string(getenv("SIMUVERITY_RUNTIME_SUBMISSION_BUNDLE"));
assetRoot = string(evaluatorAssetRoot);
assert(isfolder(runtimeRoot), "SimuVerity:F90:XMECH07:RuntimeRoot", ...
    "Fresh reference runtime bundle is missing.");
assert(isfolder(assetRoot), "SimuVerity:F90:XMECH07:AssetRoot", ...
    "Evaluator-owned reference asset root is missing.");

relativeRoot = "Spatial-Contact-Force-Examples-Simscape-Multibody";
relativeModel = fullfile(relativeRoot, "Models", "Gripper_2Belts", ...
    "Gripper_2Belts.slx");
sourceRoot = fullfile(runtimeRoot, relativeRoot);
assetSourceRoot = fullfile(assetRoot, relativeRoot);
modelFile = fullfile(runtimeRoot, relativeModel);
assert(isfile(modelPath) && localSamePath(modelPath, modelFile), ...
    "SimuVerity:F90:XMECH07:RuntimeModelPath", ...
    "Selected reference is not the task-bound runtime entrypoint.");

boundFiles = {
    fullfile("Models", "Gripper_2Belts", "Gripper_2Belts.slx"), ...
        "present"; ...
    fullfile("Libraries", "Parts_Lib.slx"), ...
        "present"; ...
    fullfile("Libraries", "Libraries", "SCF_Custom_Forces_lib.slx"), ...
        "present"; ...
    fullfile("Scripts_Data", "Point_Cloud", "Point_Cloud_Data_Brick.m"), ...
        "present"};
for index = 1:size(boundFiles, 1)
    relativePath = string(boundFiles{index, 1});
    expectedPresence = string(boundFiles{index, 2});
    localAssertAsset(fullfile(assetSourceRoot, relativePath), expectedPresence, ...
        "AssetClosureIdentity");
    localAssertAsset(fullfile(sourceRoot, relativePath), expectedPresence, ...
        "RuntimeClosureIdentity");
end
declaredPresence = lower(strtrim(string("present")));
assert(declaredPresence == string(boundFiles{1, 2}), ...
    "SimuVerity:F90:XMECH07:ReferenceBinding", ...
    "Evaluator reference file presence does not match the task binding.");

generationRunId = strtrim(string(getenv("SIMUVERITY_SCORING_RUN_ID")));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XMECH07:ScoringRunId", ...
    "SIMUVERITY_SCORING_RUN_ID is required.");
outDir = string(outputDir);
assert(~isfolder(outDir) && ~isfile(outDir), ...
    "SimuVerity:F90:XMECH07:OutputReuse", ...
    "Evidence output already exists: %s", outDir);
mkdir(outDir);

cacheDir = string(getenv("SIMULINK_CACHE_FOLDER"));
codegenDir = string(getenv("SIMULINK_CODEGEN_FOLDER"));
assert(strlength(cacheDir) > 0 && strlength(codegenDir) > 0, ...
    "SimuVerity:F90:XMECH07:Isolation", ...
    "Isolated cache and codegen folders are required.");
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");
addpath(genpath(sourceRoot), "-begin");

evidence = struct( ...
    "schema", "simuverity.f90-xmech07-evidence.v1", ...
    "task_id", "F90-XMECH-07", ...
    "reference_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "contact_evidence_aggregation", ...
        "minimum separation, resultant normal/friction magnitudes and components, force-weighted interface velocities", ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "static_audit", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "matlab_release", string(version("-release")), ...
        "mcp_port", string(getenv("SIMUVERITY_MCP_PORT")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));

model = "Gripper_2Belts";
try
    load_system(modelFile);
    cleanup = onCleanup(@() localCloseModel(model)); %#ok<NASGU>
    evidence.load_pass = true;
    paths = localModelPaths(model);
    localInstallHarness(model, paths);
    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "StopTime", "30", ...
        "SimscapeLogType", "all", ...
        "SimscapeLogName", "simlog_Gripper_2Belts", ...
        "SignalLogging", "on");
    localApplyScenario(model, paths, scenarios(1));
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(paths);

    set_param(model, "StopTime", "1");
    smoke = sim(model, "ReturnWorkspaceOutputs", "on");
    localValidateSmoke(smoke);
    evidence.nominal_smoke_pass = true;
    clear smoke
    set_param(model, "StopTime", "30");

    rows = repmat(localEmptyScenario, numel(scenarios), 1);
    for k = 1:numel(scenarios)
        scenario = scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).requested_inputs = scenario;
        try
            localApplyScenario(model, paths, scenario);
            started = tic;
            simOut = sim(model, "ReturnWorkspaceOutputs", "on");
            rows(k).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut);
            rows(k) = localFinalizeScenario(rows(k), outputs);
            clear simOut
        catch ME
            rows(k).error = localError(ME);
        end
    end
    evidence.scenarios = rows;
catch ME
    evidence.errors.session = localError(ME);
end

localCloseModel(model);
evidence.model_closed_without_save = ~bdIsLoaded(model);
evidence.finished_at = localNow;
evidencePath = fullfile(outDir, "evidence.json");
localWriteJson(evidencePath, evidence);
validCount = 0;
if ~isempty(evidence.scenarios)
    validCount = sum([evidence.scenarios.valid]);
end
fprintf("F90_XMECH07_EVIDENCE load=%d update=%d compile=%d smoke=%d valid=%d/%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    evidence.nominal_smoke_pass, validCount, ...
    numel(evidence.scenarios), evidencePath);
end

function paths = localModelPaths(model)
paths = struct( ...
    "commands", localFindRoot(model, "Commands"), ...
    "box_joint", localFindRoot(model, "Box Joint"), ...
    "box", localFindRoot(model, "Box"), ...
    "box_solid", model + "/Box/Box", ...
    "gripper", localFindRoot(model, "Gripper"), ...
    "gripper_force", localFindRoot(model, "Gripper Force"), ...
    "belt_in", localFindRoot(model, "Belt In"), ...
    "belt_out", localFindRoot(model, "Belt Out"), ...
    "force_in", localFindRoot(model, "Force Box to Belt In"), ...
    "force_out", localFindRoot(model, "Force Box to Belt Out"), ...
    "goto_in", localFindRoot(model, "Goto3"), ...
    "goto_out", localFindRoot(model, "Goto2"), ...
    "input_gain", model + "/F90 Input Belt Scale", ...
    "output_gain", model + "/F90 Output Belt Scale");
assert(getSimulinkBlockHandle(paths.box_solid) > 0, ...
    "SimuVerity:F90:XMECH07:BoxSolid", "The physical payload solid was not found.");
end

function localInstallHarness(model, paths)
add_block("simulink/Math Operations/Gain", paths.output_gain, ...
    "Gain", "1", "Position", [315 50 345 80]);
add_block("simulink/Math Operations/Gain", paths.input_gain, ...
    "Gain", "1", "Position", [315 80 345 110]);
commandPorts = get_param(paths.commands, "PortHandles");
gotoOutPorts = get_param(paths.goto_out, "PortHandles");
gotoInPorts = get_param(paths.goto_in, "PortHandles");
outputGainPorts = get_param(paths.output_gain, "PortHandles");
inputGainPorts = get_param(paths.input_gain, "PortHandles");
localReplaceLine(model, commandPorts.Outport(5), ...
    gotoOutPorts.Inport(1), outputGainPorts);
localReplaceLine(model, commandPorts.Outport(6), ...
    gotoInPorts.Inport(1), inputGainPorts);

for k = 1:4
    localTap(model, paths.commands, k, ...
        "f90_command_" + string(k));
end
localTap(model, paths.output_gain, 1, "f90_command_5");
localTap(model, paths.input_gain, 1, "f90_command_6");
localContactTaps(model, paths.force_in, "f90_input_contact");
localContactTaps(model, paths.force_out, "f90_output_contact");
end

function localReplaceLine(parent, source, destination, gainPorts)
line = get_param(source, "Line");
destinations = get_param(line, "DstPortHandle");
assert(any(destinations == destination), ...
    "SimuVerity:F90:XMECH07:BeltCommandPath", ...
    "A native belt-command connection is missing.");
delete_line(parent, source, destination);
add_line(parent, source, gainPorts.Inport(1), "autorouting", "on");
add_line(parent, gainPorts.Outport(1), destination, "autorouting", "on");
end

function localContactTaps(model, forceBlock, prefix)
selector = model + "/F90 " + prefix + " Selector";
add_block("simulink/Signal Routing/Bus Selector", selector, ...
    "OutputSignals", "sep,vn,fn,vt.x,vt.y,Ff.mag,Ff.x,Ff.y", ...
    "Position", [205 300 215 470]);
sourcePorts = get_param(forceBlock, "PortHandles");
selectorPorts = get_param(selector, "PortHandles");
add_line(model, sourcePorts.Outport(1), selectorPorts.Inport(1), ...
    "autorouting", "on");
for k = 1:8
    localTap(model, selector, k, prefix + "_" + string(k));
end
end

function localTap(parent, source, port, variable)
tap = parent + "/F90 " + variable + " Tap";
add_block("simulink/Sinks/To Workspace", tap, ...
    "VariableName", variable, "SaveFormat", "Timeseries");
sourcePorts = get_param(source, "PortHandles");
tapPorts = get_param(tap, "PortHandles");
assert(sourcePorts.Outport(port) > 0 && tapPorts.Inport(1) > 0, ...
    "SimuVerity:F90:XMECH07:TapPort", "A required real source port is missing.");
add_line(parent, sourcePorts.Outport(port), tapPorts.Inport(1), ...
    "autorouting", "on");
end

function localApplyScenario(model, paths, scenario)
names = ["InputBeltSpeedScale", "OutputBeltSpeedScale", ...
    "BeltKineticFrictionScale", "BeltStaticFrictionScale", ...
    "PayloadDensityScale"];
for name = names
    assignin("base", name, double(scenario.(name)));
end
workspace = get_param(model, "ModelWorkspace");
assignin(workspace, "cube_con_muk", ...
    0.5 * double(scenario.BeltKineticFrictionScale));
assignin(workspace, "cube_con_mus", ...
    0.7 * double(scenario.BeltStaticFrictionScale));
set_param(paths.input_gain, "Gain", ...
    localNumber(scenario.InputBeltSpeedScale));
set_param(paths.output_gain, "Gain", ...
    localNumber(scenario.OutputBeltSpeedScale));
set_param(paths.box_solid, "Density", ...
    localNumber(1000 * double(scenario.PayloadDensityScale)));
end

function localValidateSmoke(simOut)
for k = 1:6
    value = localGetOutput(simOut, "f90_command_" + string(k));
    assert(isa(value, "timeseries") && numel(value.Time) >= 1, ...
        "SimuVerity:F90:XMECH07:SmokeCommand", ...
        "Smoke run did not produce command channel %d.", k);
end
for prefix = ["f90_input_contact", "f90_output_contact"]
    for k = 1:8
        value = localGetOutput(simOut, prefix + "_" + string(k));
        assert(isa(value, "timeseries") && numel(value.Time) >= 1, ...
            "SimuVerity:F90:XMECH07:SmokeContact", ...
            "Smoke run did not produce %s channel %d.", prefix, k);
    end
end
simlog = localGetOutput(simOut, "simlog_Gripper_2Belts");
assert(~isempty(simlog), "SimuVerity:F90:XMECH07:SmokeSimlog", ...
    "Smoke run did not produce the native Simscape log.");
localJointSeries(simlog, "Px", "p", "m");
end

function outputs = localExtractOutputs(simOut)
time = linspace(0, 30, 3001)';
simlog = localGetOutput(simOut, "simlog_Gripper_2Belts");
assert(~isempty(simlog), "SimuVerity:F90:XMECH07:Simlog", ...
    "The native Simscape log is missing.");
box = [ ...
    localInterp(localJointSeries(simlog, "Px", "p", "m"), time), ...
    localInterp(localJointSeries(simlog, "Py", "p", "m"), time), ...
    localInterp(localJointSeries(simlog, "Pz", "p", "m"), time), ...
    localInterp(localJointSeries(simlog, "Px", "v", "m/s"), time), ...
    localInterp(localJointSeries(simlog, "Py", "v", "m/s"), time), ...
    localInterp(localJointSeries(simlog, "Pz", "v", "m/s"), time)];
commands = zeros(numel(time), 6);
for k = 1:6
    commands(:, k) = localInterp(localWorkspaceSeries(simOut, ...
        "f90_command_" + string(k)), time);
end
inputContact = localContactMatrix(simOut, "f90_input_contact", time);
outputContact = localContactMatrix(simOut, "f90_output_contact", time);
outputs = struct( ...
    "time_s", time, ...
    "box_state", box, ...
    "command_state", commands, ...
    "input_contact", inputContact, ...
    "output_contact", outputContact);
end

function matrix = localContactMatrix(simOut, prefix, time)
native = cell(1, 8);
for k = 1:8
    native{k} = localInterpMatrix(localWorkspaceSeries(simOut, ...
        prefix + "_" + string(k)), time);
end
% The native Spatial Contact Force bus is point-cloud resolved.  Preserve
% the physical interface resultants rather than silently selecting the
% first contact point.
normalWeight = abs(native{3});
frictionWeight = abs(native{6});
matrix = [ ...
    min(native{1}, [], 2), ...
    localWeightedInterfaceMean(native{2}, normalWeight), ...
    sum(native{3}, 2), ...
    localWeightedInterfaceMean(native{4}, frictionWeight), ...
    localWeightedInterfaceMean(native{5}, frictionWeight), ...
    sum(abs(native{6}), 2), ...
    sum(native{7}, 2), ...
    sum(native{8}, 2)];
end

function series = localJointSeries(simlog, axis, quantity, unit)
try
    node = simlog.Box_Joint.(char(axis)).(char(quantity)).series;
    nativeTime = node.time;
    nativeValues = node.values(char(unit));
    series = struct( ...
        "time", double(nativeTime(:)), ...
        "values", squeeze(double(nativeValues)));
catch ME
    error("SimuVerity:F90:XMECH07:JointSeries", ...
        "Required native Box Joint %s.%s series is missing: %s", ...
        axis, quantity, ME.message);
end
end

function series = localWorkspaceSeries(simOut, name)
value = localGetOutput(simOut, name);
assert(isa(value, "timeseries"), "SimuVerity:F90:XMECH07:WorkspaceTap", ...
    "Required measurement tap %s is missing.", name);
raw = double(value.Data);
sampleCount = numel(value.Time);
dimensions = size(raw);
if sampleCount == 1
    data = reshape(raw, 1, []);
else
    timeDimension = [];
    if dimensions(1) == sampleCount
        timeDimension = 1;
    elseif dimensions(end) == sampleCount
        timeDimension = numel(dimensions);
    else
        matches = find(dimensions == sampleCount, 1, "first");
        if ~isempty(matches), timeDimension = matches; end
    end
    assert(~isempty(timeDimension), "SimuVerity:F90:XMECH07:WorkspaceShape", ...
        "Tap %s has no dimension matching its %d timestamps.", ...
        name, sampleCount);
    order = [timeDimension, setdiff(1:numel(dimensions), ...
        timeDimension, "stable")];
    data = reshape(permute(raw, order), sampleCount, []);
end
assert(size(data, 1) == sampleCount && ~isempty(data), ...
    "SimuVerity:F90:XMECH07:WorkspaceShape", ...
    "Tap %s has unexpected dimensions.", name);
series = struct("time", double(value.Time(:)), "values", data);
end

function values = localInterp(series, time)
values = localInterpMatrix(series, time);
assert(size(values, 2) == 1, "SimuVerity:F90:XMECH07:ScalarTap", ...
    "A required scalar tap unexpectedly contains %d channels.", ...
    size(values, 2));
values = double(values(:, 1));
end

function values = localInterpMatrix(series, time)
assert(~isempty(series.time) && ~isempty(series.values), ...
    "SimuVerity:F90:XMECH07:EmptySeries", "Required series is empty.");
sourceTime = double(series.time(:));
sourceValues = double(series.values);
if isvector(sourceValues), sourceValues = sourceValues(:); end
[sourceTime, uniqueIndex] = unique(sourceTime, "stable");
sourceValues = sourceValues(uniqueIndex, :);
if numel(sourceTime) == 1
    values = repmat(sourceValues(1, :), numel(time), 1);
else
    values = interp1(sourceTime, sourceValues, time, ...
        "linear", "extrap");
end
values = double(values);
end

function values = localWeightedInterfaceMean(data, weights)
if size(data, 2) == size(weights, 2)
    denominator = sum(weights, 2);
    values = sum(data .* weights, 2) ./ max(denominator, eps);
    inactive = denominator <= eps;
    if any(inactive)
        values(inactive) = mean(data(inactive, :), 2);
    end
else
    values = mean(data, 2);
end
end

function row = localFinalizeScenario(row, outputs)
allValues = [outputs.time_s; outputs.box_state(:); ...
    outputs.command_state(:); outputs.input_contact(:); ...
    outputs.output_contact(:)];
row.simulation_pass = true;
row.required_evidence_pass = all(isfinite(allValues)) && ...
    numel(outputs.time_s) == 3001 && ...
    outputs.time_s(1) == 0 && outputs.time_s(end) >= 30;
row.valid = row.required_evidence_pass;
row.sample_count = numel(outputs.time_s);
row.start_time_s = outputs.time_s(1);
row.end_time_s = outputs.time_s(end);
row.outputs = outputs;
row.error = struct;
end

function audit = localStaticAudit(paths)
audit = struct( ...
    "free_six_dof_payload_joint", ...
        getSimulinkBlockHandle(paths.box_joint) > 0, ...
    "physical_payload_solid", ...
        getSimulinkBlockHandle(paths.box_solid) > 0, ...
    "input_belt_mechanism", ...
        getSimulinkBlockHandle(paths.belt_in) > 0, ...
    "output_belt_mechanism", ...
        getSimulinkBlockHandle(paths.belt_out) > 0, ...
    "input_normal_and_friction_contact", ...
        getSimulinkBlockHandle(paths.force_in) > 0, ...
    "output_normal_and_friction_contact", ...
        getSimulinkBlockHandle(paths.force_out) > 0, ...
    "active_gripper_mechanism", ...
        getSimulinkBlockHandle(paths.gripper) > 0, ...
    "finite_compliance_gripper_contact", ...
        getSimulinkBlockHandle(paths.gripper_force) > 0, ...
    "four_gripper_command_channels", ...
        localCommandPath(paths.commands, paths.gripper, 4), ...
    "independent_scaled_belt_commands", ...
        localPortConnects(paths.output_gain, 1, paths.goto_out, 1) && ...
        localPortConnects(paths.input_gain, 1, paths.goto_in, 1));
values = struct2cell(audit);
audit.core_path_qualified = all(cellfun(@(value) logical(value), values));
end

function pass = localCommandPath(commands, gripper, count)
pass = true;
for k = 1:count
    pass = pass && localPortConnects(commands, k, gripper, k);
end
end

function pass = localPortConnects(source, outIndex, destination, inIndex)
pass = false;
try
    sourcePorts = get_param(source, "PortHandles");
    destinationPorts = get_param(destination, "PortHandles");
    line = get_param(sourcePorts.Outport(outIndex), "Line");
    destinations = get_param(line, "DstPortHandle");
    pass = any(destinations == destinationPorts.Inport(inIndex));
catch
end
end

function path = localFindRoot(model, expected)
blocks = find_system(model, "SearchDepth", 1, "Type", "Block");
matches = strings(0, 1);
for k = 1:numel(blocks)
    name = string(get_param(blocks{k}, "Name"));
    normalized = strtrim(regexprep(name, "\s+", " "));
    if strcmpi(normalized, expected)
        matches(end + 1, 1) = string(blocks{k}); %#ok<AGROW>
    end
end
assert(numel(matches) == 1, "SimuVerity:F90:XMECH07:BlockLookup", ...
    "Expected one root block named %s, found %d.", ...
    expected, numel(matches));
path = matches(1);
end

function output = localGetOutput(simOut, name)
output = [];
try, output = simOut.get(name); catch, end
if isempty(output)
    try, output = evalin("base", name); catch, end
end
end

function localCloseModel(model)
try
    if bdIsLoaded(model), close_system(model, 0); end
catch
end
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "requested_inputs", struct, ...
    "simulation_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "simulation_wall_clock_s", 0, ...
    "sample_count", 0, ...
    "start_time_s", 0, ...
    "end_time_s", 0, ...
    "outputs", struct, ...
    "error", struct);
end

function info = localError(ME)
info = struct("identifier", string(ME.identifier), ...
    "message", string(ME.message));
end

function value = localNumber(value)
value = sprintf("%.17g", double(value));
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

function localAssertAsset(pathValue, expectedPresence, suffix)
assert(isfile(pathValue), "SimuVerity:F90:XMECH07:AssetIdentity", ...
    "%s: a reference-bound file is missing: %s", suffix, pathValue);
assert(strcmpi(localFilePresence(pathValue), expectedPresence), ...
    "SimuVerity:F90:XMECH07:AssetIdentity", ...
    "%s: a reference-bound file binding differs: %s", suffix, pathValue);
end

function same = localSamePath(firstPath, secondPath)
first = char(java.io.File(char(firstPath)).getCanonicalPath());
second = char(java.io.File(char(secondPath)).getCanonicalPath());
if ispc
    same = strcmpi(first, second);
else
    same = strcmp(first, second);
end
end

function contract = localOfficialScenarios(value)
if isstruct(value)
    contract = value;
else
    scenarioPath = string(value);
    assert(isfile(scenarioPath), "SimuVerity:F90:XMECH07:OfficialScenarios", ...
        "Official scenarios are missing: %s", scenarioPath);
    contract = jsondecode(fileread(scenarioPath));
end
assert(isfield(contract, "schema") && ...
    string(contract.schema) == "simuverity.official-scenarios.v1" && ...
    isfield(contract, "task_id") && ...
    string(contract.task_id) == "F90-XMECH-07" && ...
    isfield(contract, "scenarios") && ...
    isfield(contract, "simulation"), ...
    "SimuVerity:F90:XMECH07:OfficialScenarioContract", ...
    "The public official scenario contract is invalid.");
rows = contract.scenarios;
if iscell(rows), rows = [rows{:}]; end
expectedIds = [ ...
    "native_nominal_transfer", ...
    "moderate_low_belt_friction", ...
    "moderate_high_belt_friction", ...
    "moderate_slow_belts", ...
    "belt_speed_mismatch", ...
    "heavier_payload_boundary"];
names = [ ...
    "InputBeltSpeedScale", ...
    "OutputBeltSpeedScale", ...
    "BeltKineticFrictionScale", ...
    "BeltStaticFrictionScale", ...
    "PayloadDensityScale"];
expectedValues = [ ...
    1.00 1.00 1.00 1.00 1.00; ...
    1.00 1.00 0.80 0.80 1.00; ...
    1.00 1.00 1.20 1.20 1.00; ...
    0.85 0.85 1.00 1.00 1.00; ...
    1.10 0.90 1.00 1.00 1.00; ...
    1.00 1.00 1.00 1.00 1.25];
assert(numel(rows) == 6, "SimuVerity:F90:XMECH07:OfficialScenarioCount", ...
    "F90-XMECH-07 requires exactly six official scenarios.");
for index = 1:numel(rows)
    row = rows(index);
    actual = zeros(1, numel(names));
    for fieldIndex = 1:numel(names)
        field = names(fieldIndex);
        assert(isfield(row, field), ...
            "SimuVerity:F90:XMECH07:OfficialScenarioFields", ...
            "Official scenario %d is missing %s.", index, field);
        actual(fieldIndex) = double(row.(field));
    end
    assert(string(row.id) == expectedIds(index) && ...
        isequal(actual, expectedValues(index, :)), ...
        "SimuVerity:F90:XMECH07:OfficialScenarioIdentity", ...
        "Official F90-XMECH-07 scenario %d is missing or changed.", index);
end
simulation = contract.simulation;
assert(double(simulation.start_s) == 0 && ...
    double(simulation.stop_s) == 30 && ...
    string(simulation.solver) == "ode23t" && ...
    double(simulation.maximum_step_s) == 0.01, ...
    "SimuVerity:F90:XMECH07:OfficialSimulationIdentity", ...
    "The official simulation contract is missing or changed.");
contract.scenarios = rows;
end

function localWriteJson(path, value)
fid = fopen(path, "w");
assert(fid > 0, "SimuVerity:F90:XMECH07:JsonWrite", ...
    "Could not open JSON output: %s", path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
bytes = unicode2native(jsonencode(value, PrettyPrint=true), "UTF-8");
fwrite(fid, bytes, "uint8");
end

function value = localNow
value = string(datetime("now", ...
    "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end
